pub fn getList(self: *Scripts, log: *logger.Log, lockfile: *const Lockfile, folder_path: *bun.AbsPath(.{.sep=.auto}), folder_name: []const u8, resolution: *const Resolution) !?Package.Scripts.List {
            if (self.hasAny()) {
                var add_node_gyp_rebuild_script = false;
                _ = &add_node_gyp_rebuild_script;
                if (((lockfile.hasTrustedDependency(folder_name, resolution) and self.install.isEmpty()) and self.preinstall.isEmpty())) {
                    var save = folder_path.save();
                    _ = &save;
                    defer {
                    _ = save.restore();
                    }
                    _ = folder_path.append("binding.gyp");
                    add_node_gyp_rebuild_script = bun.sys.exists(folder_path.slice());
                }
                return self.createList(lockfile, lockfile.buffers.string_bytes.items, folder_path, folder_name, resolution.tag, add_node_gyp_rebuild_script);
            } else {
                if ((!self.filled)) {
                    return self.createFromPackageJSON(log, lockfile, folder_path, folder_name, resolution.tag);
                }
            }
            return null;
    }

pub fn fillFromPackageJSON(self: *Scripts, allocator: std.mem.Allocator, string_builder: *Lockfile.StringBuilder, log: *logger.Log, folder_path: *bun.AbsPath(.{.sep=.auto})) !void {
            var save = folder_path.save();
            _ = &save;
            defer {
            _ = save.restore();
            }
            _ = folder_path.append("package.json");
            const buf = try bun.sys.File.readFrom(bun.FD.cwd(), folder_path.sliceZ(), allocator).unwrap();
            const json_src = logger.Source.initPathString(folder_path.slice(), buf);
            _ = initializeStore();
            const json = try JSON.parsePackageJSONUTF8(json_src, log, allocator);
            _ = Lockfile.Package.Scripts.parseCount(allocator, string_builder, json);
            _ = try string_builder.allocate();
            _ = self.parseAlloc(allocator, string_builder, json);
            self.filled = true;
    }

pub fn createFromPackageJSON(self: *Scripts, log: *logger.Log, lockfile: *const Lockfile, folder_path: *bun.AbsPath(.{.sep=.auto}), folder_name: []const u8, resolution_tag: Resolution.Tag) !?Package.Scripts.List {
            var tmp: Lockfile = undefined;
            _ = &tmp;
            _ = tmp.initEmpty(lockfile.allocator);
            defer {
            _ = tmp.deinit();
            }
            var builder = tmp.stringBuilder();
            _ = &builder;
            _ = try self.fillFromPackageJSON(lockfile.allocator, builder, log, folder_path);
            var add_node_gyp_rebuild_script = false;
            _ = &add_node_gyp_rebuild_script;
            if ((self.install.isEmpty() and self.preinstall.isEmpty())) {
                const save = folder_path.save();
                defer {
                _ = save.restore();
                }
                _ = folder_path.append("binding.gyp");
                add_node_gyp_rebuild_script = bun.sys.exists(folder_path.slice());
            }
            return self.createList(lockfile, tmp.buffers.string_bytes.items, folder_path, folder_name, resolution_tag, add_node_gyp_rebuild_script);
    }
    pub const List = ScriptsList;
};

const stringZ = [:0]const u8;
const OptString = ?[]const u8;
